commands.command:
set -eu
WT="$HOME/agent-workspace/repos/photomap/worktrees/unified-ux-20261104-v1"
ROOT="$HOME/agent-workspace/repos/photomap/work"
export PYTHON="$ROOT/backend/.venv/bin/python"
export E2E_CHROME_EXECUTABLE="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
cd "$WT/frontend"
TMP_SPEC="e2e/visual/zz-unified-ux-screenshot-review.spec.ts"
trap 'rm -f "$TMP_SPEC"' EXIT
cat > "$TMP_SPEC" <<'EOF'
import { expect, test } from "@playwright/test";
import { mockSharedApi } from "../support/visualApi";
test("inspect unified map panels on desktop and mobile", async ({ page }, testInfo) => {
  test.setTimeout(120_000);
  for (const viewport of [{ width: 390, height: 844 }, { width: 1440, height: 900 }]) {
    await page.setViewportSize(viewport);
    await mockSharedApi(page);
    await page.goto("/");
    const tour = page.locator(".map-tour");
    if (await tour.isVisible()) {
      await tour.getByRole("button", { name: "Pomiń", exact: true }).click();
    }
    await expect(page.locator(".place-photo-marker").first()).toBeVisible();
    await page.getByRole("button", { name: "Filtry mapy" }).click();
    await expect(page.locator("#map-tools-panel")).toBeVisible();
    await page.screenshot({ path: testInfo.outputPath(`ux-${viewport.width}-filters.png`), animations: "disabled" });
    await page.getByRole("button", { name: "Ustawienia widoku mapy" }).click();
    await page.screenshot({ path: testInfo.outputPath(`ux-${viewport.width}-view.png`), animations: "disabled" });
  }
});
EOF
npm run test:e2e -- "$TMP_SPEC" --workers=1 --reporter=line
for n in ux-390-filters ux-390-view ux-1440-filters; do
  IMG=$(find test-results -name "$n.png" -type f -print -quit)
  if [ -z "$IMG" ]; then echo "MISSING_$n"; exit 1; fi
  JPG="/tmp/photomap-$n-review.jpg"
  sips -s format jpeg -s formatOptions 26 -Z 420 "$IMG" --out "$JPG" >/dev/null
  printf 'UX_VISUAL_%s ' "$n"
  base64 -i "$JPG" | tr -d '\n'
  printf '\n'
done
